import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
import io
from jinja2 import Environment, FileSystemLoader, Template
import json
import os

sns.set_theme(style="whitegrid")

def fig_to_base64(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight')
    buf.seek(0)
    img_str = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return img_str

def main():
    # Load data
    df = pd.read_csv('/app/benchmark/data.csv')

    # KPIs
    total_books = len(df)
    unique_books = df['Name'].nunique()
    genre_counts = df['Genre'].value_counts()
    avg_price = df['Price'].mean()
    avg_rating = df['User Rating'].mean()
    avg_reviews = df['Reviews'].mean()

    corr_coef = df['Price'].corr(df['User Rating'])

    # 1. Bestseller Market Overview
    overview = {
        'total_books': total_books,
        'unique_books': unique_books,
        'fiction_count': int(genre_counts.get('Fiction', 0)),
        'non_fiction_count': int(genre_counts.get('Non Fiction', 0)),
        'avg_price': round(avg_price, 2),
        'avg_rating': round(avg_rating, 2),
        'avg_reviews': round(avg_reviews, 0)
    }

    # 2. Price vs Rating Scatter
    fig, ax = plt.subplots(figsize=(8, 5))
    sns.scatterplot(data=df, x='Price', y='User Rating', hue='Genre', alpha=0.6, ax=ax)
    ax.set_title('Price vs. User Rating by Genre')
    ax.set_xlabel('Price ($)')
    ax.set_ylabel('User Rating')
    scatter_b64 = fig_to_base64(fig)

    # 3. Genre Comparison
    genre_stats = df.groupby('Genre').agg({
        'Price': 'mean',
        'User Rating': 'mean',
        'Reviews': 'mean'
    }).round(2).reset_index()

    fig, axes = plt.subplots(1, 3, figsize=(15, 5))
    sns.barplot(data=genre_stats, x='Genre', y='Price', ax=axes[0], palette='pastel')
    axes[0].set_title('Average Price ($)')
    sns.barplot(data=genre_stats, x='Genre', y='User Rating', ax=axes[1], palette='pastel')
    axes[1].set_title('Average User Rating')
    sns.barplot(data=genre_stats, x='Genre', y='Reviews', ax=axes[2], palette='pastel')
    axes[2].set_title('Average Reviews')
    plt.tight_layout()
    genre_b64 = fig_to_base64(fig)

    # 4. Temporal Trends
    yearly_stats = df.groupby(['Year', 'Genre']).agg({
        'Price': 'mean',
        'User Rating': 'mean',
        'Reviews': 'mean'
    }).reset_index()

    fig, axes = plt.subplots(3, 1, figsize=(10, 15))
    sns.lineplot(data=yearly_stats, x='Year', y='Price', hue='Genre', marker='o', ax=axes[0])
    axes[0].set_title('Average Price Over Time')
    axes[0].set_ylabel('Price ($)')

    sns.lineplot(data=yearly_stats, x='Year', y='User Rating', hue='Genre', marker='o', ax=axes[1])
    axes[1].set_title('Average User Rating Over Time')
    axes[1].set_ylabel('User Rating')

    sns.lineplot(data=yearly_stats, x='Year', y='Reviews', hue='Genre', marker='o', ax=axes[2])
    axes[2].set_title('Average Reviews Over Time')
    axes[2].set_ylabel('Reviews')
    plt.tight_layout()
    trends_b64 = fig_to_base64(fig)

    # 5. Top Authors
    author_counts = df['Author'].value_counts().head(10).reset_index()
    author_counts.columns = ['Author', 'Appearances']
    # merge with avg rating and price for these authors
    author_stats = df[df['Author'].isin(author_counts['Author'])].groupby('Author').agg({
        'Price': 'mean',
        'User Rating': 'mean'
    }).reset_index()
    top_authors = pd.merge(author_counts, author_stats, on='Author').sort_values('Appearances', ascending=False)

    fig, ax = plt.subplots(figsize=(10, 6))
    sns.barplot(data=top_authors, y='Author', x='Appearances', palette='viridis', ax=ax)
    ax.set_title('Top 10 Authors by Bestseller Appearances')
    authors_b64 = fig_to_base64(fig)

    top_authors_dict = top_authors.to_dict(orient='records')
    for row in top_authors_dict:
        row['Price'] = round(row['Price'], 2)
        row['User Rating'] = round(row['User Rating'], 2)

    # 6. HTML Template
    template_str = """
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <title>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)</title>
        <style>
            :root {
                --primary: #2c3e50;
                --secondary: #34495e;
                --accent: #3498db;
                --light: #ecf0f1;
                --text: #333;
            }
            body {
                font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
                color: var(--text);
                background-color: #f8f9fa;
                margin: 0;
                padding: 0;
                line-height: 1.6;
            }
            .container {
                max-width: 1200px;
                margin: 0 auto;
                padding: 40px 20px;
                background-color: white;
                box-shadow: 0 0 10px rgba(0,0,0,0.05);
            }
            header {
                text-align: center;
                margin-bottom: 50px;
                border-bottom: 2px solid var(--light);
                padding-bottom: 30px;
            }
            h1 {
                color: var(--primary);
                font-size: 2.5em;
                margin-bottom: 10px;
            }
            h2 {
                color: var(--secondary);
                border-bottom: 1px solid var(--light);
                padding-bottom: 10px;
                margin-top: 40px;
            }
            h3 {
                color: var(--accent);
            }
            .subtitle {
                font-size: 1.2em;
                color: #7f8c8d;
                max-width: 800px;
                margin: 0 auto;
            }
            .kpi-container {
                display: flex;
                justify-content: space-between;
                flex-wrap: wrap;
                margin-bottom: 40px;
            }
            .kpi-card {
                background: var(--light);
                padding: 20px;
                border-radius: 8px;
                flex: 1;
                margin: 10px;
                min-width: 200px;
                text-align: center;
                box-shadow: 0 2px 5px rgba(0,0,0,0.05);
            }
            .kpi-value {
                font-size: 2em;
                font-weight: bold;
                color: var(--primary);
                margin: 10px 0;
            }
            .kpi-label {
                font-size: 0.9em;
                color: #7f8c8d;
                text-transform: uppercase;
                letter-spacing: 1px;
            }
            .section {
                margin-bottom: 50px;
            }
            .chart-container {
                text-align: center;
                margin: 30px 0;
            }
            img {
                max-width: 100%;
                height: auto;
                border-radius: 4px;
                box-shadow: 0 4px 6px rgba(0,0,0,0.1);
            }
            table {
                width: 100%;
                border-collapse: collapse;
                margin: 20px 0;
            }
            th, td {
                padding: 12px 15px;
                text-align: left;
                border-bottom: 1px solid #ddd;
            }
            th {
                background-color: var(--primary);
                color: white;
            }
            tr:hover {
                background-color: #f5f5f5;
            }
            .recommendations {
                background-color: #e8f4f8;
                padding: 30px;
                border-radius: 8px;
                border-left: 5px solid var(--accent);
            }
            .recommendations ul {
                padding-left: 20px;
            }
            .recommendations li {
                margin-bottom: 15px;
            }
            .footer {
                text-align: center;
                margin-top: 50px;
                padding-top: 20px;
                border-top: 1px solid var(--light);
                color: #7f8c8d;
                font-size: 0.9em;
            }
        </style>
    </head>
    <body>
        <div class="container">
            <header>
                <h1>Amazon Bestselling Books: Price vs. User Rating Trend Analysis</h1>
                <p class="subtitle">A comprehensive analysis of how book pricing strategies relate to customer satisfaction across Fiction and Non-Fiction genres over a decade of Amazon bestseller data (2009–2019).</p>
            </header>

            <div class="section" id="market-overview">
                <h2>Bestseller Market Overview (2009–2019)</h2>
                <p>Over the 11-year period, the Amazon bestseller lists featured {{ overview.total_books }} total appearances by {{ overview.unique_books }} unique books. The market was fairly evenly split, with Non-Fiction slightly edging out Fiction.</p>

                <div class="kpi-container">
                    <div class="kpi-card">
                        <div class="kpi-label">Average User Rating</div>
                        <div class="kpi-value">{{ overview.avg_rating }} / 5.0</div>
                    </div>
                    <div class="kpi-card">
                        <div class="kpi-label">Average Book Price</div>
                        <div class="kpi-value">${{ overview.avg_price }}</div>
                    </div>
                    <div class="kpi-card">
                        <div class="kpi-label">Average Review Count</div>
                        <div class="kpi-value">{{ overview.avg_reviews }}</div>
                    </div>
                    <div class="kpi-card">
                        <div class="kpi-label">Fiction vs Non-Fiction</div>
                        <div class="kpi-value">{{ overview.fiction_count }} / {{ overview.non_fiction_count }}</div>
                    </div>
                </div>
            </div>

            <div class="section" id="price-rating-correlation">
                <h2>Price vs. User Rating: Correlation Analysis</h2>
                <p>The central question of this analysis is whether price drives user satisfaction. Our findings show a very weak, slightly negative correlation between price and user rating. The Pearson correlation coefficient is <strong>{{ corr_coef }}</strong>.</p>
                <p>This suggests that paying a premium for a bestseller does not guarantee higher satisfaction. In fact, many lower-priced books achieve near-perfect ratings, likely driven by promotional pricing on established favorites or highly accessible fiction.</p>

                <div class="chart-container">
                    <img src="data:image/png;base64,{{ scatter_b64 }}" alt="Price vs User Rating Scatter Plot">
                </div>
            </div>

            <div class="section" id="genre-comparison">
                <h2>Fiction vs. Non-Fiction: Pricing and Rating Strategies</h2>
                <p>When segmenting by genre, distinct strategies emerge. Non-Fiction titles command a higher average price but receive fewer reviews on average. Fiction titles, despite being priced lower, tend to generate significantly more engagement (reviews) and maintain competitive ratings.</p>

                <div class="chart-container">
                    <img src="data:image/png;base64,{{ genre_b64 }}" alt="Genre Comparison Charts">
                </div>
            </div>

            <div class="section" id="temporal-trends">
                <h2>Year-over-Year Trends in Pricing and Ratings</h2>
                <p>A temporal analysis reveals significant shifts in pricing strategy over the decade. Notably, average prices for both genres saw a steep decline from 2009 to 2014, stabilizing in recent years. Meanwhile, user ratings have steadily climbed, indicating that readers are paying less but reporting higher satisfaction—a win for the consumer but a margin compression challenge for publishers.</p>

                <div class="chart-container">
                    <img src="data:image/png;base64,{{ trends_b64 }}" alt="Temporal Trends Charts">
                </div>
            </div>

            <div class="section" id="top-authors">
                <h2>Dominant Authors on the Bestseller List</h2>
                <p>Certain authors maintain a perennial presence on the bestseller list. Analyzing their average pricing and ratings provides a benchmark for sustained success.</p>

                <div class="chart-container">
                    <img src="data:image/png;base64,{{ authors_b64 }}" alt="Top Authors Bar Chart">
                </div>

                <table>
                    <thead>
                        <tr>
                            <th>Author</th>
                            <th>Bestseller Appearances</th>
                            <th>Average Price ($)</th>
                            <th>Average Rating</th>
                        </tr>
                    </thead>
                    <tbody>
                        {% for author in top_authors %}
                        <tr>
                            <td>{{ author.Author }}</td>
                            <td>{{ author.Appearances }}</td>
                            <td>{{ author.Price }}</td>
                            <td>{{ author['User Rating'] }}</td>
                        </tr>
                        {% endfor %}
                    </tbody>
                </table>
            </div>

            <div class="section" id="recommendations">
                <h2>Strategic Recommendations</h2>
                <div class="recommendations">
                    <ul>
                        <li><strong>Avoid Overpricing for Perceived Value:</strong> The negligible correlation ({{ corr_coef }}) between price and rating indicates that readers do not equate a higher price with a better book. Keep prices competitive, especially for Fiction titles where volume drives engagement.</li>
                        <li><strong>Leverage the Fiction Review Engine:</strong> Fiction books generate substantially higher review volumes. Use aggressive promotional pricing (or free first-in-series tactics) on Fiction to build an insurmountable review moat, which algorithmically sustains sales.</li>
                        <li><strong>Protect Non-Fiction Margins:</strong> Non-Fiction readers are historically less price-sensitive and willing to pay a premium. Maintain higher price points for authoritative Non-Fiction, but ensure quality is uncompromised to maintain high ratings in a lower-volume review environment.</li>
                        <li><strong>Adapt to the New Price Baseline:</strong> The temporal data shows the era of $15+ average prices is largely behind us. Catalog planning must assume lower per-unit revenue and optimize for higher volume or alternative monetization streams.</li>
                    </ul>
                </div>
            </div>

            <div class="footer">
                <p>Report generated by Automated Data Intelligence System.</p>
                <p>Data Source: Amazon Bestsellers (2009-2019)</p>
            </div>
        </div>
    </body>
    </html>
    """

    template = Template(template_str)
    html_out = template.render(
        overview=overview,
        corr_coef=round(corr_coef, 3),
        scatter_b64=scatter_b64,
        genre_b64=genre_b64,
        trends_b64=trends_b64,
        authors_b64=authors_b64,
        top_authors=top_authors_dict
    )

    os.makedirs('/app/output', exist_ok=True)
    with open('/app/output/final_report.html', 'w', encoding='utf-8') as f:
        f.write(html_out)

    print("Report generated successfully at /app/output/final_report.html")

if __name__ == '__main__':
    main()
